      "Reference": "WHO standard acupuncture point locations in the Western Pacific Region. World Health Organization. Regional Office for the Western Pacific, 2008. Page 62",
      "Indications": "Pain in the lumbar and iliac region, coldness of the knee, paralysis or motor impairment and pain of the lower extremities, beriberi.",
